import{_ as t,o,c as a,a2 as c}from"./chunks/framework.CvydjLy7.js";const f=JSON.parse('{"title":"8.13 小结与下一步","description":"","frontmatter":{"title":"8.13 小结与下一步"},"headers":[],"relativePath":"ch08/13.md","filePath":"ch08/13.md","lastUpdated":1789497795000}'),r={name:"ch08/13.md"};function d(i,e,s,l,n,_){return o(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="_8-13-小结与下一步" tabindex="-1">8.13 小结与下一步 <a class="header-anchor" href="#_8-13-小结与下一步" aria-label="Permalink to &quot;8.13 小结与下一步&quot;">​</a></h1><p>这一篇做的事：</p><ul><li>判断该不该上消息队列的三条标准，以及引入后必然多出来的四件事（重复消费、顺序、失败处理、本地跑不起来）</li><li>Kafka：Boot 4 新增的 <code>spring-boot-starter-kafka</code>、key 与分区的关系（实测同 key 三条全落分区 0）、发送返回的 Future 不等确认</li><li>消费失败的处理：默认无限重试会堵死分区，配 <code>DefaultErrorHandler</code> + 死信；<strong>死信默认后缀是 <code>-dlt</code> 不是 <code>.DLT</code></strong></li><li>RabbitMQ：交换机与队列的拓扑声明、死信参数、<code>Jackson2JsonMessageConverter</code> 已废弃</li><li>发布确认与退回的分工；消费者确认、prefetch、重投行为</li><li>WebSocket + STOMP 的三种前缀、两种推送方式、多实例的坑，以及 <code>WebSocketStompClient</code> 的包名迁移</li><li>三条链路的测试手法，7 个用例、约 10 秒、零外部依赖</li></ul><p>工程侧新增 <code>activity-server-messaging</code>，19 个 Java 文件 996 行，7 个测试全通过。</p><p>下一篇处理测试本身：单元测试与集成测试的边界怎么划、切片测试怎么用（以及 <code>@WebMvcTest</code> 在 4.x 的包名变化）、端到端测试改用 <code>RestTestClient</code>（它会连带讲清 <code>TestRestTemplate</code> 只是换了模块和包名，并没有废弃）、以及用 Testcontainers 起真实数据库。</p>',5)])])}const m=t(r,[["render",d]]);export{f as __pageData,m as default};
